   153  static const format_info *
   154  find_format(pgp_symm_alg_t cipher, pgp_cipher_mode_t mode, pgp_hash_alg_t hash_alg)
   155  {
   156      for (size_t i = 0; i < ARRAY_SIZE(formats); i++) {
   157          if (formats[i].cipher == cipher && formats[i].cipher_mode == mode &&
   158              formats[i].hash_alg == hash_alg) {
   159              return &formats[i];
   160          }
   161      }
   162      return NULL;
   163  }
